function decodeEntities(s) {
  return s
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/&quot;/gi, '"')
    .replace(/&#39;/gi, "'")
    .replace(/&apos;/gi, "'")
    .replace(/&#x([0-9a-f]+);/gi, (_, h) => String.fromCharCode(parseInt(h, 16)))
    .replace(/#(\d+);/g, (_, d) => String.fromCharCode(parseInt(d, 10)));
}

function htmlToText(html) {
  if (!html) return '';
  let s = String(html);
  s = s.replace(/<script[\s\S]*?<\/script>/gi, '');
  s = s.replace(/<style[\s\S]*?<\/style>/gi, '');
  s = s.replace(/<!--[\s\S]*?-->/g, '');
  s = s.replace(/<head[\s\S]*?<\/head>/gi, '');
  s = s.replace(/<\/td\s*>/gi, '\t');
  s = s.replace(/<\/th\s*>/gi, '\t');
  s = s.replace(/<\/tr\s*>/gi, '\n');
  s = s.replace(/<br\s*\/?>/gi, '\n');
  s = s.replace(/<\/p\s*>/gi, '\n');
  s = s.replace(/<\/div\s*>/gi, '\n');
  s = s.replace(/<\/h[1-6]\s*>/gi, '\n');
  s = s.replace(/<\/li\s*>/gi, '\n');
  s = s.replace(/<[^>]+>/g, ' ');
  s = decodeEntities(s);
  s = s.split('\n')
    .map(line => line.replace(/[ \t\f\v]+/g, ' ').trim())
    .filter(line => line.length > 0)
    .join('\n');
  return s.substring(0, 16000);
}

const results = [];
for (let i = 0; i < items.length; i++) {
  const item = items[i];
  const json = item.json || {};

  // Gmail simplified output: html/text/snippet + From string. Outlook-style object shape kept as fallback.
  let bodyContent = '';
  let isHtml = false;
  if (json.html) { bodyContent = json.html; isHtml = true; }
  else if (json.text) { bodyContent = json.text; }
  else if (json.snippet) { bodyContent = json.snippet; }
  else if (json.body && json.body.content) { bodyContent = json.body.content; isHtml = (json.body.contentType === 'html'); }
  const invoiceText = isHtml ? htmlToText(bodyContent) : String(bodyContent || '').substring(0, 16000);

  let emailFrom = '';
  const fromRaw = json.From || json.from || '';
  if (typeof fromRaw === 'string') {
    emailFrom = fromRaw;
  } else if (fromRaw && fromRaw.emailAddress) {
    emailFrom = (fromRaw.emailAddress.name || '') + ' <' + (fromRaw.emailAddress.address || '') + '>';
  }

  // Identify PDF attachments among the binaries Gmail already downloaded
  const binary = item.binary || {};
  const pdfKeys = [];
  const pdfNames = [];
  for (const key of Object.keys(binary)) {
    const b = binary[key] || {};
    const name = String(b.fileName || '').toLowerCase();
    const mime = String(b.mimeType || '').toLowerCase();
    if (name.endsWith('.pdf') || mime.includes('pdf')) {
      pdfKeys.push(key);
      pdfNames.push(b.fileName || key);
    }
  }

  // Copy first PDF to a fixed key so Extract From File can find it
  const outBinary = Object.assign({}, binary);
  if (pdfKeys.length > 0) {
    outBinary.pdfDoc = binary[pdfKeys[0]];
  }

  results.push({
    json: {
      invoiceContent: invoiceText,
      emailSubject: json.Subject || json.subject || '',
      emailFrom: emailFrom,
      emailDate: json.date || json.receivedDateTime || '',
      emailUid: json.id || '',
      hasAttachment: pdfKeys.length > 0,
      pdfKeys: pdfKeys,
      pdfNames: pdfNames
    },
    binary: outBinary
  });
}

return results;

// Re-attach metadata + binary from the Prepare node. Extract From File replaces json on success,
// and items without a PDF (errored with continueRegularOutput) pass through here untouched.
const prep = $('Decode Gmail Entities').all();
const out = [];
for (let i = 0; i < items.length; i++) {
  const src = prep[i] || items[i];
  const base = Object.assign({}, src.json);
  const j = items[i].json || {};
  const pdfText = (typeof j.text === 'string') ? j.text : '';
  if (pdfText.trim().length > 0) {
    const label = (base.pdfNames && base.pdfNames[0]) ? base.pdfNames[0] : 'document';
    base.invoiceContent = String(base.invoiceContent || '') +
      '\n\n===== ATTACHED PDF: ' + label + ' =====\n' +
      pdfText.replace(/[ \t]+\n/g, '\n').substring(0, 16000);
    base.pdfTextExtracted = true;
  } else {
    base.pdfTextExtracted = false;
  }
  out.push({ json: base, binary: src.binary });
}
return out;

function parseInvoiceJson(raw) {
  let cleaned = String(raw || '').trim()
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/\s*```$/i, '')
    .trim();
  let parsed = {};
  try {
    const tmp = JSON.parse(cleaned);
    if (tmp && typeof tmp === 'object' && !Array.isArray(tmp)) parsed = tmp;
  } catch(e) {
    const m = cleaned.match(/\{[\s\S]*\}/);
    if (m) {
      try {
        const tmp2 = JSON.parse(m[0]);
        if (tmp2 && typeof tmp2 === 'object' && !Array.isArray(tmp2)) parsed = tmp2;
      } catch(e2) {}
    }
  }
  return parsed;
}

const invoiceFields = ['invoiceNumber','poNumber','vendorName','contactInfo','issueDate','dueDate',
  'subtotal','taxAmount','totalAmountDue','currency','paymentTerms','description',
  'quantityHours','unitPrice','paymentStatus'];

const receiptFields = ['receiptVendorName','receiptInvoiceNumber','receiptAmount','receiptDate',
  'receiptPaymentMethod','receiptReference'];

const allFields = invoiceFields.concat(receiptFields);

const metaItems = $('Combine PDF Metadata and Text').all();
const out = [];
for (let i = 0; i < items.length; i++) {
  const parsed = parseInvoiceJson(items[i].json.text);
  const row = {};
  for (const f of allFields) {
    const v = parsed[f];
    row[f] = (v !== null && v !== undefined) ? String(v) : '';
  }
  row.documentType = parsed.documentType || '';
  const metaItem = metaItems[i] || null;
  const meta = metaItem ? (metaItem.json || {}) : {};
  row.emailSubject = meta.emailSubject || '';
  row.emailFrom = meta.emailFrom || '';
  row.emailDate = meta.emailDate || '';
  row.emailUid = meta.emailUid || '';
  row.hasAttachment = meta.hasAttachment || false;
  row.pdfKeys = meta.pdfKeys || [];
  row.pdfNames = meta.pdfNames || [];
  out.push({ json: row, binary: metaItem ? metaItem.binary : undefined });
}

return out;

function normalizeVendor(v) {
  return String(v || '')
    .toUpperCase()
    .replace(/[.,'"`]/g, '')
    .replace(/\b(INC|LLC|LTD|LP|LLP|CORP|CO|COMPANY|CORPORATION|GROUP|HOLDINGS|SERVICES|GMBH|PLC)\b/g, '')
    .replace(/[^A-Z0-9]+/g, '')
    .trim();
}

function normalizeInvNum(n) {
  return String(n || '')
    .toUpperCase()
    .replace(/[^A-Z0-9]+/g, '')
    .trim();
}

function normalizeAmount(a) {
  const num = parseFloat(String(a || '').replace(/[^0-9.-]+/g, ''));
  if (isNaN(num)) return '';
  return num.toFixed(2);
}

function sig(vendor, invNum, amount) {
  return normalizeVendor(vendor) + '|' + normalizeInvNum(invNum) + '|' + normalizeAmount(amount);
}

function sigAlt(vendor, amount, dateStr) {
  return normalizeVendor(vendor) + '|' + normalizeAmount(amount) + '|' + String(dateStr || '').substring(0, 10);
}

function vendorAmountKey(vendor, amount) {
  return normalizeVendor(vendor) + '|' + normalizeAmount(amount);
}

function parseDateMs(s) {
  const t = Date.parse(String(s || '').substring(0, 10));
  return isNaN(t) ? null : t;
}

const MATCH_WINDOW_MS = 60 * 24 * 60 * 60 * 1000; // 60 days

const existing = $('Fetch Invoices from Sheets').all();
const existingBySig = new Map();
const existingBySigAlt = new Map();
const existingByVendorAmount = new Map();

for (const e of existing) {
  const r = e.json || {};
  const vendor = r['Vendor / Client Name'] || '';
  const invNum = r['Invoice Number'] || '';
  const amount = r['Total Amount Due'] || '';
  const issueDate = r['Issue Date'] || '';
  const dueDate = r['Due Date'] || '';
  const paymentStatus = r['Payment Status'] || 'Unpaid';
  const euid = r['EUID'] || '';
  if (!vendor || !amount) continue;

  if (invNum) {
    const s = sig(vendor, invNum, amount);
    if (!existingBySig.has(s)) existingBySig.set(s, { euid: euid, paymentStatus: paymentStatus });
  } else if (issueDate) {
    const s2 = sigAlt(vendor, amount, issueDate);
    if (!existingBySigAlt.has(s2)) existingBySigAlt.set(s2, { euid: euid, paymentStatus: paymentStatus });
  }

  if (paymentStatus !== 'Paid' && euid) {
    const vk = vendorAmountKey(vendor, amount);
    if (!existingByVendorAmount.has(vk)) existingByVendorAmount.set(vk, []);
    existingByVendorAmount.get(vk).push({ euid: euid, issueDate: issueDate, dueDate: dueDate });
  }
}

const withinRunInvoiceBySig = new Map();
for (let i = 0; i < items.length; i++) {
  const r = items[i].json;
  const docType = r.documentType || (r.invoiceNumber ? 'invoice' : 'other');
  if (docType === 'invoice' && r.vendorName && r.invoiceNumber && r.totalAmountDue) {
    withinRunInvoiceBySig.set(sig(r.vendorName, r.invoiceNumber, r.totalAmountDue), i);
  }
}

const seenThisRun = new Set();
const seenAltThisRun = new Set();
const out = [];
const pendingPaidUpdates = [];

for (let i = 0; i < items.length; i++) {
  const r = Object.assign({}, items[i].json);
  let docType = r.documentType || (r.invoiceNumber ? 'invoice' : 'other');
  if (docType !== 'invoice' && docType !== 'receipt') docType = 'other';
  r.documentType = docType;
  r.isDuplicate = false;
  r.dupReason = '';
  r.isMatched = false;
  r.matchType = '';
  r.matchedEUID = '';
  r.matchReason = '';
  r.needsAttachmentProcessing = false;
  r.excelAction = 'none';

  if (docType === 'invoice') {
    const vendor = r.vendorName || '';
    const invNum = r.invoiceNumber || '';
    const amount = r.totalAmountDue || '';
    const issueDate = r.issueDate || '';
    if (vendor && invNum && amount) {
      const s = sig(vendor, invNum, amount);
      if (existingBySig.has(s)) {
        r.isDuplicate = true;
        r.dupReason = 'already in spreadsheet';
      } else if (seenThisRun.has(s)) {
        r.isDuplicate = true;
        r.dupReason = 'duplicate within this run';
      } else {
        seenThisRun.add(s);
      }
    } else if (vendor && amount && issueDate) {
      // Fallback dedup for invoices that have no invoice number
      const s2 = sigAlt(vendor, amount, issueDate);
      if (existingBySigAlt.has(s2)) {
        r.isDuplicate = true;
        r.dupReason = 'already in spreadsheet (no invoice #: vendor/amount/date matched)';
      } else if (seenAltThisRun.has(s2)) {
        r.isDuplicate = true;
        r.dupReason = 'duplicate within this run';
      } else {
        seenAltThisRun.add(s2);
      }
    }
    r.excelAction = r.isDuplicate ? 'none' : 'append';
    r.needsAttachmentProcessing = !r.isDuplicate;
  } else if (docType === 'receipt') {
    const vendor = r.receiptVendorName || '';
    const invNum = r.receiptInvoiceNumber || '';
    const amount = r.receiptAmount || '';
    let matchedWithinRunIndex = -1;

    if (vendor && invNum && amount) {
      const s = sig(vendor, invNum, amount);
      if (withinRunInvoiceBySig.has(s)) {
        matchedWithinRunIndex = withinRunInvoiceBySig.get(s);
        r.isMatched = true;
        r.matchType = 'same-run';
      } else if (existingBySig.has(s)) {
        r.isMatched = true;
        r.matchType = 'exact';
        r.matchedEUID = existingBySig.get(s).euid;
      }
    }

    if (!r.isMatched && vendor && amount) {
      const vk = vendorAmountKey(vendor, amount);
      const allCandidates = existingByVendorAmount.get(vk) || [];
      const rMs = parseDateMs(r.receiptDate);
      let candidates = allCandidates;
      if (rMs !== null && allCandidates.length > 0) {
        candidates = allCandidates.filter(function(c) {
          const dueMs = parseDateMs(c.dueDate);
          const issMs = parseDateMs(c.issueDate);
          const cMs = (dueMs !== null) ? dueMs : issMs;
          if (cMs === null) return true; // row has no usable date - keep as candidate
          return Math.abs(rMs - cMs) <= MATCH_WINDOW_MS;
        });
      }
      if (candidates.length === 1) {
        r.isMatched = true;
        r.matchType = 'fuzzy';
        r.matchedEUID = candidates[0].euid;
      } else if (candidates.length > 1) {
        r.matchReason = candidates.length + ' possible matches for this vendor/amount - manual review needed';
      } else if (allCandidates.length > 0) {
        r.matchReason = 'vendor/amount matched but outside 60-day date window - manual review needed';
      } else {
        r.matchReason = 'no matching invoice found';
      }
    }

    if (r.matchType === 'exact' || r.matchType === 'fuzzy') {
      r.excelAction = 'update';
    } else {
      r.excelAction = 'none';
    }
    // Save receipt PDFs regardless of match outcome (matched, unmatched, or same-run)
    r.needsAttachmentProcessing = true;

    if (matchedWithinRunIndex >= 0) {
      pendingPaidUpdates.push({
        targetIndex: matchedWithinRunIndex,
        receiptDate: r.receiptDate,
        receiptReference: r.receiptReference,
        emailSubject: r.emailSubject
      });
    }
  }

  out.push({ json: r, binary: items[i].binary });
}

for (let k = 0; k < pendingPaidUpdates.length; k++) {
  const upd = pendingPaidUpdates[k];
  const target = out[upd.targetIndex];
  if (target) {
    target.json.paymentStatus = 'Paid';
    target.json.paidDate = upd.receiptDate || '';
    target.json.paymentReference = upd.receiptReference || upd.emailSubject || 'Matched to receipt in same batch';
  }
}

return out;

return items.map(function(item) {
  const r = item.json;
  const docType = r.documentType || 'other';

  const base = {
    'Email UID': r.emailUid || '',
    hasAttachment: r.hasAttachment || false,
    pdfKeys: r.pdfKeys || [],
    pdfNames: r.pdfNames || [],
    documentType: docType,
    isDuplicate: r.isDuplicate || false,
    dupReason: r.dupReason || '',
    isMatched: r.isMatched || false,
    matchType: r.matchType || '',
    matchedEUID: r.matchedEUID || '',
    matchReason: r.matchReason || '',
    needsAttachmentProcessing: r.needsAttachmentProcessing || false,
    excelAction: r.excelAction || 'none',
    emailSubject: r.emailSubject || '',
    emailFrom: r.emailFrom || '',
    emailDate: r.emailDate || ''
  };

  let json = base;

  if (docType === 'invoice') {
    const paymentStatus = r.paymentStatus === 'Paid' ? 'Paid' : 'Unpaid';
    const paidDate = paymentStatus === 'Paid' ? (r.paidDate || r.emailDate || '') : '';
    const paymentReference = paymentStatus === 'Paid' ? (r.paymentReference || 'Stated in invoice text') : '';

    json = Object.assign({}, base, {
      'Invoice Number': r.invoiceNumber || '',
      'PO Number': r.poNumber || '',
      'Vendor / Client Name': r.vendorName || '',
      'Contact Info': r.contactInfo || '',
      'Issue Date': r.issueDate || '',
      'Due Date': r.dueDate || '',
      'Subtotal': r.subtotal || '',
      'Tax Amount': r.taxAmount || '',
      'Total Amount Due': r.totalAmountDue || '',
      'Currency': r.currency || '',
      'Payment Terms': r.paymentTerms || '',
      'Description': r.description || '',
      'Quantity / Hours': r.quantityHours || '',
      'Unit Price / Rate': r.unitPrice || '',
      'Source Email From': r.emailFrom || '',
      'Source Email Subject': r.emailSubject || '',
      'Email Received Date': r.emailDate || '',
      'Processed At': new Date().toISOString(),
      'Payment Status': paymentStatus,
      'Paid Date': paidDate,
      'Payment Reference': paymentReference,
      vendorNameRaw: r.vendorName || '',
      issueDateRaw: r.issueDate || ''
    });
  } else if (docType === 'receipt') {
    json = Object.assign({}, base, {
      'Receipt Vendor': r.receiptVendorName || '',
      'Receipt Invoice Number': r.receiptInvoiceNumber || '',
      'Receipt Amount': r.receiptAmount || '',
      'Receipt Date': r.receiptDate || '',
      'Receipt Payment Method': r.receiptPaymentMethod || '',
      'Receipt Reference': r.receiptReference || '',
      receiptDate: r.receiptDate || '',
      receiptReference: r.receiptReference || '',
      vendorNameRaw: r.receiptVendorName || '',
      issueDateRaw: r.receiptDate || ''
    });
  }

  return { json: json, binary: item.binary };
});

// Fan out: one output item per PDF attachment, carrying its binary under 'pdfFile'.
const out = [];
const today = new Date();
const pad = (n) => String(n).padStart(2, '0');
const folderName = today.getFullYear() + '-' + pad(today.getMonth() + 1) + '-' + pad(today.getDate());

function slugify(s, max) {
  return String(s || '')
    .toUpperCase()
    .replace(/[^A-Z0-9]/g, '-')
    .replace(/-+/g, '-')
    .replace(/^-|-$/g, '')
    .substring(0, max);
}

for (let i = 0; i < items.length; i++) {
  const row = items[i].json || {};
  const binary = items[i].binary || {};
  const keys = Array.isArray(row.pdfKeys) ? row.pdfKeys : [];
  const validKeys = keys.filter(function(k) { return binary[k]; });

  let vendorSlug = slugify(row.vendorNameRaw || 'UNKNOWN', 30);
  if (!vendorSlug) vendorSlug = 'UNKNOWN';

  const invRaw = (row.documentType === 'receipt')
    ? (row['Receipt Invoice Number'] || row['Receipt Reference'] || '')
    : (row['Invoice Number'] || '');
  const invSlug = slugify(invRaw, 20);

  let dateStr = '';
  const m = String(row.issueDateRaw || '').match(/(\d{4})-(\d{2})(?:-(\d{2}))?/);
  if (m) {
    dateStr = m[3] ? (m[1] + '-' + m[2] + '-' + m[3]) : (m[1] + '-' + m[2]);
  } else {
    dateStr = folderName;
  }

  const suffix = (row.documentType === 'receipt') ? 'RECEIPT' : '';

  if (validKeys.length === 0) {
    // No usable PDF binary - keep the item flowing so it still reaches the Sheet and the digest.
    out.push({ json: Object.assign({}, row, {
      folderName: folderName,
      fileName: '',
      pdfPart: 0,
      noPdfBinary: true
    }) });
    continue;
  }

  for (let k = 0; k < validKeys.length; k++) {
    const parts = [vendorSlug];
    if (invSlug) {
      parts.push(invSlug);
      parts.push(dateStr);
    } else {
      parts.push(dateStr);
    }
    if (suffix) parts.push(suffix);
    if (validKeys.length > 1) parts.push('P' + (k + 1));
    const fileName = parts.join('-') + '.pdf';

    out.push({
      json: Object.assign({}, row, {
        folderName: folderName,
        fileName: fileName,
        pdfPart: k + 1,
        noPdfBinary: false
      }),
      binary: { pdfFile: binary[validKeys[k]] }
    });
  }
}

return out;

// Group upload results back to ONE item per email; join all PDF links.
// Positional alignment with 'Code — Build Upload Path' is 1:1 (uploads preserve order).
const uploads = $('Generate Paths for PDF Uploads').all();
const byEmail = new Map();
const order = [];

for (let i = 0; i < items.length; i++) {
  const row = (uploads[i] && uploads[i].json) ? uploads[i].json : {};
  const resp = items[i].json || {};
  const webUrl = (typeof resp.webViewLink === 'string') ? resp.webViewLink : '';
  const downloadUrl = (typeof resp.webContentLink === 'string') ? resp.webContentLink : '';
  const link = webUrl || downloadUrl || '';
  const uid = row['Email UID'] || ('item-' + i);

  if (!byEmail.has(uid)) {
    const clean = Object.assign({}, row);
    delete clean.folderName;
    delete clean.fileName;
    delete clean.pdfPart;
    delete clean.noPdfBinary;
    delete clean.pdfKeys;
    delete clean.pdfNames;
    delete clean.vendorNameRaw;
    delete clean.issueDateRaw;
    delete clean.hasAttachment;
    byEmail.set(uid, { row: clean, links: [] });
    order.push(uid);
  }
  if (link) byEmail.get(uid).links.push(link);
}

return order.map(function(uid) {
  const e = byEmail.get(uid);
  return { json: Object.assign({}, e.row, { pdfLink: e.links.join(' | ') }) };
});

// No PDF attachment to save — pass items through with empty pdfLink
return items.map(function(item) {
  const clean = Object.assign({}, item.json);
  delete clean.hasAttachment;
  delete clean.vendorNameRaw;
  delete clean.issueDateRaw;
  delete clean.pdfKeys;
  delete clean.pdfNames;
  clean.pdfLink = '';
  return { json: clean };
});

const cfg = $('Configure Workflow Settings').first().json;
const today = new Date().toLocaleDateString('en-US', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' });

// Google Drive folder link — comes straight from Set — Config
const driveFolderUrl = cfg.driveFolderUrl || '#';

const esc = (s) => String(s == null ? '' : s)
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;');

function getRow(it) {
  return it.json;
}

function formatMoney(amount, currency) {
  if (!amount) return 'N/A';
  const num = parseFloat(String(amount).replace(/[^0-9.-]+/g, ''));
  const code = (currency || 'USD').trim().toUpperCase();
  if (isNaN(num)) return String(amount);
  try {
    return new Intl.NumberFormat('en-US', { style: 'currency', currency: code }).format(num);
  } catch (e) {
    return new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD' }).format(num);
  }
}

const newRows = [];
const dupRows = [];
const matchedReceipts = [];
const unmatchedReceipts = [];

for (const it of items) {
  const r = getRow(it);
  if (r.documentType === 'invoice') {
    if (r.isDuplicate) dupRows.push(r); else newRows.push(r);
  } else if (r.documentType === 'receipt') {
    if (r.matchType === 'exact' || r.matchType === 'fuzzy') matchedReceipts.push(r);
    else if (r.matchType !== 'same-run') unmatchedReceipts.push(r);
  }
}

const newCount = newRows.length;
const dupCount = dupRows.length;
const matchedCount = matchedReceipts.length;
const unmatchedCount = unmatchedReceipts.length;

if (newCount === 0 && dupCount === 0 && matchedCount === 0 && unmatchedCount === 0) {
  return [{ json: {
    subject: 'Invoice Digest – ' + today + ' – Nothing to Report',
    body: '<p>No invoice or receipt emails were detected in this run (' + today + ').</p>'
  }}];
}

function renderRow(r) {
  const inv = r['Invoice Number'] || 'N/A';
  const vendor = r['Vendor / Client Name'] || 'N/A';
  const issue = r['Issue Date'] || 'N/A';
  const due = r['Due Date'] || 'N/A';
  const total = formatMoney(r['Total Amount Due'], r['Currency']);
  const from = r['Source Email From'] || 'N/A';
  const status = r['Payment Status'] || 'Unpaid';
  const statusColor = status === 'Paid' ? '#1D9E75' : '#888780';
  return '<tr>' +
    '<td style="padding:6px 8px;border:1px solid #ddd;">' + esc(inv) + '</td>' +
    '<td style="padding:6px 8px;border:1px solid #ddd;">' + esc(vendor) + '</td>' +
    '<td style="padding:6px 8px;border:1px solid #ddd;">' + esc(issue) + '</td>' +
    '<td style="padding:6px 8px;border:1px solid #ddd;">' + esc(due) + '</td>' +
    '<td style="padding:6px 8px;border:1px solid #ddd;text-align:right;">' + esc(total) + '</td>' +
    '<td style="padding:6px 8px;border:1px solid #ddd;color:' + statusColor + ';font-weight:bold;">' + esc(status) + '</td>' +
    '<td style="padding:6px 8px;border:1px solid #ddd;font-size:12px;">' + esc(from) + '</td>' +
    '</tr>';
}

function renderDupRow(r) {
  const inv = r['Invoice Number'] || 'N/A';
  const vendor = r['Vendor / Client Name'] || 'N/A';
  const total = formatMoney(r['Total Amount Due'], r['Currency']);
  const from = r['Source Email From'] || 'N/A';
  const reason = r.dupReason || 'duplicate';
  return '<tr>' +
    '<td style="padding:6px 8px;border:1px solid #ddd;">' + esc(inv) + '</td>' +
    '<td style="padding:6px 8px;border:1px solid #ddd;">' + esc(vendor) + '</td>' +
    '<td style="padding:6px 8px;border:1px solid #ddd;text-align:right;">' + esc(total) + '</td>' +
    '<td style="padding:6px 8px;border:1px solid #ddd;font-size:12px;">' + esc(from) + '</td>' +
    '<td style="padding:6px 8px;border:1px solid #ddd;font-size:12px;color:#888;font-style:italic;">' + esc(reason) + '</td>' +
    '</tr>';
}

function renderMatchedReceipt(r) {
  const vendor = r['Receipt Vendor'] || 'N/A';
  const amount = formatMoney(r['Receipt Amount'], '');
  const date = r['Receipt Date'] || 'N/A';
  const method = r['Receipt Payment Method'] || 'N/A';
  const matchLabel = r.matchType === 'exact' ? 'exact match' : 'vendor + amount match';
  return '<tr>' +
    '<td style="padding:6px 8px;border:1px solid #ddd;">' + esc(vendor) + '</td>' +
    '<td style="padding:6px 8px;border:1px solid #ddd;text-align:right;">' + esc(amount) + '</td>' +
    '<td style="padding:6px 8px;border:1px solid #ddd;">' + esc(date) + '</td>' +
    '<td style="padding:6px 8px;border:1px solid #ddd;">' + esc(method) + '</td>' +
    '<td style="padding:6px 8px;border:1px solid #ddd;font-size:12px;color:#888;">' + esc(matchLabel) + '</td>' +
    '</tr>';
}

function renderUnmatchedReceipt(r) {
  const vendor = r['Receipt Vendor'] || 'N/A';
  const amount = formatMoney(r['Receipt Amount'], '');
  const date = r['Receipt Date'] || 'N/A';
  const from = r.emailFrom || 'N/A';
  const reason = r.matchReason || 'no matching invoice found';
  return '<tr>' +
    '<td style="padding:6px 8px;border:1px solid #ddd;">' + esc(vendor) + '</td>' +
    '<td style="padding:6px 8px;border:1px solid #ddd;text-align:right;">' + esc(amount) + '</td>' +
    '<td style="padding:6px 8px;border:1px solid #ddd;">' + esc(date) + '</td>' +
    '<td style="padding:6px 8px;border:1px solid #ddd;font-size:12px;">' + esc(from) + '</td>' +
    '<td style="padding:6px 8px;border:1px solid #ddd;font-size:12px;color:#993c1d;font-style:italic;">' + esc(reason) + '</td>' +
    '</tr>';
}

const tableHeader =
  '<thead><tr style="background:#002657;color:#fff;">' +
  '<th style="padding:8px;border:1px solid #ddd;">Invoice #</th>' +
  '<th style="padding:8px;border:1px solid #ddd;">Vendor / Client</th>' +
  '<th style="padding:8px;border:1px solid #ddd;">Issue Date</th>' +
  '<th style="padding:8px;border:1px solid #ddd;">Due Date</th>' +
  '<th style="padding:8px;border:1px solid #ddd;">Total Due</th>' +
  '<th style="padding:8px;border:1px solid #ddd;">Status</th>' +
  '<th style="padding:8px;border:1px solid #ddd;">Source Email</th>' +
  '</tr></thead>';

const dupTableHeader =
  '<thead><tr style="background:#8a6d3b;color:#fff;">' +
  '<th style="padding:8px;border:1px solid #ddd;">Invoice #</th>' +
  '<th style="padding:8px;border:1px solid #ddd;">Vendor / Client</th>' +
  '<th style="padding:8px;border:1px solid #ddd;">Total Due</th>' +
  '<th style="padding:8px;border:1px solid #ddd;">Source Email</th>' +
  '<th style="padding:8px;border:1px solid #ddd;">Reason</th>' +
  '</tr></thead>';

const matchedTableHeader =
  '<thead><tr style="background:#0f6e56;color:#fff;">' +
  '<th style="padding:8px;border:1px solid #ddd;">Vendor</th>' +
  '<th style="padding:8px;border:1px solid #ddd;">Amount</th>' +
  '<th style="padding:8px;border:1px solid #ddd;">Payment Date</th>' +
  '<th style="padding:8px;border:1px solid #ddd;">Method</th>' +
  '<th style="padding:8px;border:1px solid #ddd;">Match Type</th>' +
  '</tr></thead>';

const unmatchedTableHeader =
  '<thead><tr style="background:#993c1d;color:#fff;">' +
  '<th style="padding:8px;border:1px solid #ddd;">Vendor</th>' +
  '<th style="padding:8px;border:1px solid #ddd;">Amount</th>' +
  '<th style="padding:8px;border:1px solid #ddd;">Date</th>' +
  '<th style="padding:8px;border:1px solid #ddd;">Source Email</th>' +
  '<th style="padding:8px;border:1px solid #ddd;">Why it needs review</th>' +
  '</tr></thead>';

let bodyParts = ['<!DOCTYPE html><html><body style="font-family:Arial,sans-serif;color:#222;">'];
bodyParts.push('<h2 style="color:#002657;">Invoice Digest – ' + esc(today) + '</h2>');

if (newCount > 0) {
  bodyParts.push('<p><strong>' + newCount + ' new invoice(s)</strong> were detected, extracted, and logged.</p>');
  bodyParts.push('<table style="border-collapse:collapse;width:100%;font-size:13px;">');
  bodyParts.push(tableHeader);
  bodyParts.push('<tbody>' + newRows.map(renderRow).join('') + '</tbody>');
  bodyParts.push('</table>');
}

if (matchedCount > 0) {
  bodyParts.push('<h3 style="color:#0f6e56;margin-top:30px;">' + matchedCount + ' Receipt(s) Matched — Marked Paid</h3>');
  bodyParts.push('<table style="border-collapse:collapse;width:100%;font-size:13px;">');
  bodyParts.push(matchedTableHeader);
  bodyParts.push('<tbody>' + matchedReceipts.map(renderMatchedReceipt).join('') + '</tbody>');
  bodyParts.push('</table>');
}

if (unmatchedCount > 0) {
  bodyParts.push('<h3 style="color:#993c1d;margin-top:30px;">' + unmatchedCount + ' Receipt(s) Need Manual Review</h3>');
  bodyParts.push('<p style="font-size:13px;color:#555;">No confident match was found in the spreadsheet — check these by hand.</p>');
  bodyParts.push('<table style="border-collapse:collapse;width:100%;font-size:13px;">');
  bodyParts.push(unmatchedTableHeader);
  bodyParts.push('<tbody>' + unmatchedReceipts.map(renderUnmatchedReceipt).join('') + '</tbody>');
  bodyParts.push('</table>');
}

if (dupCount > 0) {
  bodyParts.push('<h3 style="color:#8a6d3b;margin-top:30px;">' + dupCount + ' Duplicate(s) Skipped</h3>');
  bodyParts.push('<p style="font-size:13px;color:#555;">These invoices match existing entries and were not added to the spreadsheet or saved to Google Drive. The emails were still marked as read.</p>');
  bodyParts.push('<table style="border-collapse:collapse;width:100%;font-size:13px;">');
  bodyParts.push(dupTableHeader);
  bodyParts.push('<tbody>' + dupRows.map(renderDupRow).join('') + '</tbody>');
  bodyParts.push('</table>');
}

if (newCount > 0 || matchedCount > 0) {
  bodyParts.push('<div style="text-align: center; margin-top: 35px; margin-bottom: 25px;">');
  bodyParts.push('<a href="' + driveFolderUrl + '" style="background-color: #002657; color: #ffffff; padding: 12px 24px; text-decoration: none; border-radius: 6px; font-weight: bold; display: inline-block; font-size: 14px;">📁 Open Google Drive Folder</a>');
  bodyParts.push('</div>');
}

bodyParts.push('<p style="margin-top:20px;font-size:12px;color:#888;">Processed emails have been marked as read and labeled Processed.</p>');
bodyParts.push('</body></html>');

const body = bodyParts.join('\n');

const subjectParts = [];
if (newCount > 0) subjectParts.push(newCount + ' Invoice(s)');
if (matchedCount > 0) subjectParts.push(matchedCount + ' Paid');
if (unmatchedCount > 0) subjectParts.push(unmatchedCount + ' Receipt(s) to Review');
if (dupCount > 0) subjectParts.push(dupCount + ' Duplicate(s)');
const subjectTail = subjectParts.length ? ' – ' + subjectParts.join(', ') : '';

return [{ json: {
  subject: 'Invoice Digest – ' + today + subjectTail,
  body: body
}}];
